import json
import logging
import os
import time

ROUTE_ID = 'text-embedding-3-small__direct__invoke'
WORKLOAD_IDS = ('openai_api.text-embedding-3-small.openai.embeddings.create.plain',)
CALL_SITES = (('app/index.py', 8),)
SOURCE_MODEL = 'text-embedding-3-small'
REGION = 'us-east-1'
MODEL_ID = 'amazon.titan-embed-text-v2:0'
MIGRATION_PATH = 'direct'
CLIENT_API = 'invoke'
